import math

def count_three_divisors(n):
 limit = math.isqrt(n)
 if limit < 2:
 return 0
 is_prime = bytearray([1]) * (limit + 1)
 is_prime[0] = is_prime[1] = 0
 for i in range(2, math.isqrt(limit) + 1):
 if is_prime[i]:
 is_prime[i * i : limit + 1 : i] = bytearray([0]) * len(range(i * i, limit + 1, i))
 return sum(is_prime)

n = int(input().strip())
print(count_three_divisors(n))

